import React, { useState, useEffect } from 'react';
import { createUser } from '../services/api';
import { getFranchises } from '../services/api'; // Import API function to get franchises
import UserManagement from './UserMangement';

const CreateUser = () => {
  const [formData, setFormData] = useState({
    username: '',
    password: '',
    name: '',
    role: 'user', // Default value
    franchiseId: '',
  });

  const [franchises, setFranchises] = useState([]); // State to store the franchises
  const [isAdminExists, setIsAdminExists] = useState(false); // State to check if admin already exists

  // Fetch the list of franchises when the component mounts
  useEffect(() => {
    const fetchFranchises = async () => {
      try {
        const response = await getFranchises();
        setFranchises(response.data); // Store the franchise data
      } catch (error) {
        alert('Error fetching franchises: ' + (error.response?.data?.message || error.message));
      }
    };
    fetchFranchises();
  }, []); // Empty dependency array to run only once when the component mounts

  // Check if an admin already exists
  useEffect(() => {
    const checkAdminExistence = async () => {
      try {
        const response = await getFranchises(); // Assuming it returns franchises with admin field
        const adminExists = response.data.some(franchise => franchise.admin);
        setIsAdminExists(adminExists);
      } catch (error) {
        alert('Error checking admin existence: ' + (error.response?.data?.message || error.message));
      }
    };
    checkAdminExistence();
  }, []);

  const handleChange = (e) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();

    // If the role is admin and an admin already exists, show error alert
    if (formData.role === 'admin' && isAdminExists) {
      alert('Only one admin can be created for all franchises.');
      return;
    }

    try {
      await createUser(formData); // Use the utility function
      alert('User created successfully!');
      window.location.reload();
    } catch (error) {
      alert('Error creating user: ' + (error.response?.data?.message || error.message));
    }
  };

  return (
    <div>
      <h1>Create User</h1>
      <form onSubmit={handleSubmit}>
        <div>
          <label htmlFor="username">Username:</label>
          <input
            id="username"
            name="username"
            placeholder="Username"
            value={formData.username}
            onChange={handleChange}
            required
          />
        </div>
        <div>
          <label htmlFor="password">Password:</label>
          <input
            id="password"
            name="password"
            type="password"
            placeholder="Password"
            value={formData.password}
            onChange={handleChange}
            required
          />
        </div>
        <div>
          <label htmlFor="name">Name:</label>
          <input
            id="name"
            name="name"
            placeholder="Full Name"
            value={formData.name}
            onChange={handleChange}
            required
          />
        </div>
        <div>
          <label htmlFor="role">Role:</label>
          <select
            id="role"
            name="role"
            value={formData.role}
            onChange={handleChange}
            disabled={isAdminExists} // Disable role selection if admin already exists
          >
            <option value="user">User</option>
            <option value="admin" disabled={isAdminExists}>Admin</option>
          </select>
        </div>
        <div>
          <label htmlFor="franchiseId">Franchise:</label>
          <select
            id="franchiseId"
            name="franchiseId"
            value={formData.franchiseId}
            onChange={handleChange}
            required
          >
            <option value="">Select a Franchise</option>
            {franchises.map((franchise) => (
              <option key={franchise._id} value={franchise._id}>
                {franchise.name} - {franchise.location}
              </option>
            ))}
          </select>
        </div>
        <button type="submit">Create User</button>
      </form>
      <UserManagement />
    </div>
  );
};

export default CreateUser;
